java.log(result);
if(String(result).match(/javascript/)){
	result=String(result).replace(/.*'(\d+)','(\d+)'.*/,'https://www.xiguashuwu4.com/book/$1/catalog/$2.html')
	java.log(result);
	result
	}else result=result

ruleContent.content:
$.url@js:
let content=""
if(result){
let b64 = java.ajax(result)
let str=java.base64Decode(b64.match(/'(.+?)'/)[1])
let list=JSON.parse(str).p
for (i =0;i<list.length;i++){
content+= list[i]+"\n"
}
}else{
content+="购买后继续阅读本章内容"
}
content

